def main() -> None:
    client = get_client()
    sheet = client.open_by_key(config.GOOGLE_SHEET_ID).worksheet(config.GOOGLE_SHEET_NAME)
    existing = sheet.get_all_values()
    existing_dates = {(r[0], r[1]) for r in existing[1:] if r}
    new_rows = [row for row in ROWS if (row[0], row[1]) not in existing_dates]
    if new_rows:
        sheet.append_rows(new_rows, value_input_option="USER_ENTERED")
    print(f"Added {len(new_rows)} records, skipped {len(ROWS) - len(new_rows)} duplicates")


if __name__ == "__main__":
    main()
